mapper.select:
select

from Dialogue

     and id = #{id}
     and user_id = #{userId}
     and course_id = #{courseId}
     and summary = #{summary}
     and update_time = #{updateTime}
     and `delete` = #{delete}
     and delete_time = #{deleteTime}
     and recent_message = #{recentMessage}
    and (`delete` IS NULL OR `delete` = FALSE)

order by update_time desc
